/*selectMasterMdCmMsdsMailSendPopList*/ SELECT A.SEQ, A.ADD_USER_ID, A.BUYER, (SELECT C.COM_NAME_LOC FROM ICOMCMPY C WHERE C.COM_CODE = A.BUYER) AS BUYER_NAME, A.RECV_USER_NAME, A.RECV_EMAIL, A.REMARK, A.STATUS FROM KEP_CMC_MAIL_INFO A WHERE 1=1 AND A.BUYER = #{st_buyer_code} AND A.STATUS = 'C' AND A.ADD_USER_ID = #{st_user_id}
AND UPPER(A.RECV_USER_NAME) LIKE UPPER( '%' || #{st_recv_user_name} || '%')
AND UPPER(A.REMARK) LIKE UPPER( '%' || #{st_remark} || '%')
